import { Component } from '@angular/core';
import { Router } from '@angular/router';
import { TaskService } from '../services/task-services';

@Component({
  selector: 'app-signup',
  templateUrl: './signup.html',
  styleUrls: ['./signup.css']
})
export class SignupComponent {
  firstName = '';
  lastName = '';
  email = '';
  mobile = '';
  password = '';
  confirmPassword = '';
  error = '';
  loading = false;

  constructor(private router: Router, private taskService: TaskService) {}

  signup() {
    if (!this.firstName || !this.lastName || !this.email || !this.mobile || !this.password) {
      this.error = 'All fields are required.';
      return;
    }
    if (this.password !== this.confirmPassword) {
      this.error = 'Passwords do not match.';
      return;
    }
    this.error = '';
    this.loading = true;

    const user = {
      first_name: this.firstName,
      last_name: this.lastName,
      email: this.email,
      mobile_number: this.mobile,
      password: this.password
    };

    this.taskService.signup(user).subscribe({
      next: () => this.router.navigate(['/']),
      error: (err) => {
        this.loading = false;
        this.error = err.error?.detail || 'Signup failed. Please try again.';
      }
    });
  }
}
<div class="bg">
  <div class="card">
    <div class="logo">
      <span class="logo-icon">✦</span>
      <h1>TaskAI</h1>
    </div>
    <p class="subtitle">Create your account</p>

    <div class="row">
      <div class="field">
        <label>First Name</label>
        <input type="text" placeholder="John" [(ngModel)]="firstName" />
      </div>
      <div class="field">
        <label>Last Name</label>
        <input type="text" placeholder="Doe" [(ngModel)]="lastName" />
      </div>
    </div>

    <div class="field">
      <label>Email <span class="hint">(used as username)</span></label>
      <input type="email" placeholder="john@example.com" [(ngModel)]="email" />
    </div>

    <div class="field">
      <label>Mobile Number</label>
      <input type="tel" placeholder="+91 9876543210" [(ngModel)]="mobile" />
    </div>

    <div class="row">
      <div class="field">
        <label>Password</label>
        <input type="password" placeholder="••••••••" [(ngModel)]="password" />
      </div>
      <div class="field">
        <label>Confirm Password</label>
        <input type="password" placeholder="••••••••" [(ngModel)]="confirmPassword" />
      </div>
    </div>

    <p class="error" *ngIf="error">{{ error }}</p>

    <button class="btn" (click)="signup()" [disabled]="loading">
      {{ loading ? 'Creating Account...' : 'Create Account →' }}
    </button>

    <p class="footer">Already have an account? <a routerLink="/">Sign in</a></p>
  </div>
</div>
